using System;
using System.Collections.Generic;
using Microsoft.EntityFrameworkCore.Migrations;

#nullable disable

namespace IepAssistant.Domain.Data.Migrations
{
    /// <summary>
    /// Data-only migration: the Ohio knowledge base (State = "OH") that the Virtual Advocate and the
    /// knowledge-base page show to Ohio families beside the federal entries seeded by
    /// <see cref="AddKnowledgeBase"/>. Every entry cites the Ohio Operating Standards (OAC Chapter 3301-51)
    /// or ORC Chapter 3323. No model change — the snapshot is untouched — and no <c>HasData</c>: the rows are
    /// inserted by <c>InsertData</c> (identity ids) and removed by <c>Down</c> by (State, Title).
    /// </summary>
    /// <remarks>
    /// <see cref="Entries"/> is public so a test can check the seed (count, required fields, column limits,
    /// unique titles, and that <c>Down</c> deletes exactly what <c>Up</c> inserted). Treat it as frozen:
    /// editing an applied migration's data does not re-run it. Post-merge content fixes go through the admin
    /// knowledge-base CRUD, not here.
    /// </remarks>
    public partial class SeedOhioKnowledgeBase : Migration
    {
        public const string StateCode = "OH";

        /// <summary>Continues after the federal seed's per-category orders (max 15) so Ohio entries sort after them on the knowledge-base page.</summary>
        public const int FirstDisplayOrder = 101;

        /// <summary>Fixed so the migration is byte-stable (the federal seed used GETUTCDATE(); a literal is friendlier to diffing and tests).</summary>
        public static readonly DateTime SeededAt = new(2026, 9, 19, 0, 0, 0, DateTimeKind.Utc);

        public sealed record Entry(string Title, string Category, string LegalReference, string Tags, string Content);

        private static readonly string[] Columns = { "Title", "Content", "Category", "LegalReference", "State", "Tags", "DisplayOrder", "IsActive", "CreatedAt", "UpdatedAt" };

        /// <inheritdoc />
        protected override void Up(MigrationBuilder migrationBuilder)
        {
            var values = new object[Entries.Count, Columns.Length];
            for (var i = 0; i < Entries.Count; i++)
            {
                var e = Entries[i];
                values[i, 0] = e.Title;
                values[i, 1] = e.Content;
                values[i, 2] = e.Category;
                values[i, 3] = e.LegalReference;
                values[i, 4] = StateCode;
                values[i, 5] = e.Tags;
                values[i, 6] = FirstDisplayOrder + i;
                values[i, 7] = true;
                values[i, 8] = SeededAt;
                values[i, 9] = SeededAt;
            }

            migrationBuilder.InsertData(
                table: "KnowledgeBaseEntries",
                columns: Columns,
                values: values);
        }

        /// <inheritdoc />
        protected override void Down(MigrationBuilder migrationBuilder)
        {
            var keys = new object[Entries.Count, 2];
            for (var i = 0; i < Entries.Count; i++)
            {
                keys[i, 0] = StateCode;
                keys[i, 1] = Entries[i].Title;
            }

            migrationBuilder.DeleteData(
                table: "KnowledgeBaseEntries",
                keyColumns: new[] { "State", "Title" },
                keyValues: keys);
        }

        /// <summary>The seeded rows, in display order. Categories: rights | process | provisions | glossary | tips.</summary>
        public static readonly IReadOnlyList<Entry> Entries = new Entry[]
        {
            new(@"Ohio's Operating Standards: the rulebook for special education", @"glossary", @"OAC 3301-51-01; ORC 3323.02", @"operating standards,OAC 3301-51,ORC 3323,rules,Ohio,who is covered",
                @"Ohio has its own rulebook for special education. It is called the Operating Standards for Ohio Educational Agencies Serving Children with Disabilities, and it lives in Chapter 3301-51 of the Ohio Administrative Code (OAC). Ohio's law on the subject is Chapter 3323 of the Ohio Revised Code (ORC). Together they say how Ohio carries out the federal law, IDEA (the Individuals with Disabilities Education Act). The standards cover every child with a disability who lives in Ohio and is between the ages of 3 and 21, including children who have been suspended or expelled. They apply to public school districts, community (charter) schools, county boards of developmental disabilities and other public agencies that serve children with disabilities. Why this matters to you: when a school says ""we have to do it this way,"" the answer should be found in these rules. Ohio's standards must give your child at least what IDEA gives, and in a few places they give more - for example, transition planning starts at age 14 in Ohio instead of 16. When the Virtual Advocate cites ""OAC 3301-51-06"" or similar, it is pointing to one of these rules so you can look it up yourself at codes.ohio.gov."),
            new(@"ETR: Ohio's name for the evaluation report", @"glossary", @"OAC 3301-51-06", @"ETR,evaluation team report,evaluation,eligibility,glossary",
                @"In Ohio, the report the school writes after evaluating your child is called the ETR, short for Evaluation Team Report. Other states and the federal law just say ""evaluation report."" Same idea, Ohio name. The ETR is written by the evaluation team, and you are part of that team. It pulls together every assessment, observation and piece of information gathered during the evaluation, describes what your child can do and where they need help, and ends with the team's decision about whether your child is eligible for special education and under which disability category. The ETR matters because everything that follows is built on it. The IEP (the plan for services) has to match what the ETR found. If the ETR misses an area, like reading fluency or anxiety, the IEP will probably miss it too. That is why it is worth reading your child's ETR closely and asking for anything missing to be added. The school must give you a copy of the ETR before the IEP meeting and no later than 14 days after the team decides on eligibility. Ohio uses a standard form for this report (form PR-06), so most ETRs look alike from district to district."),
            new(@"Who is on the IEP team in Ohio", @"glossary", @"OAC 3301-51-07(F)", @"IEP team,members,who attends,general education teacher,intervention specialist,district representative",
                @"An IEP team is the group that writes and updates your child's IEP. Under Ohio's rules the team must include: - You, the parent. You are a full member, not a guest. - At least one general education teacher, if your child is or may be in general education classes. - At least one special education teacher or provider. In Ohio this is often called an intervention specialist. - A representative of the school district who can approve services and knows the general curriculum and the district's resources. This person is often a principal or special education supervisor. - Someone who can explain what the evaluation results mean for teaching. This can be one of the people above. - Your child, when appropriate, and always when transition (planning for life after school) is being discussed. You and the school can each invite other people who know your child or have special expertise, such as a therapist, an advocate, a relative or a friend. You do not need the school's permission to bring someone. Required members can only be excused from a meeting with your written agreement, and if their area is being discussed they must give written input before the meeting."),
            new(@"Who counts as a parent, including surrogate parents", @"glossary", @"OAC 3301-51-01(B)(48); OAC 3301-51-05", @"parent definition,surrogate parent,guardian,grandparent,stepparent,foster parent",
                @"Ohio's rules define ""parent"" broadly, because the person raising a child is not always the biological parent. Under the Operating Standards, a parent can be: - A biological or adoptive parent. - A guardian who is allowed to make educational decisions for the child (but not the state itself when the child is a ward of the state). - Someone acting in place of a parent whom the child lives with, such as a grandparent, stepparent or other relative, or someone legally responsible for the child's welfare. - A surrogate parent appointed under Ohio's procedural safeguards rule. A foster parent is not automatically a parent under these rules unless one of the other categories fits. A surrogate parent is appointed when no parent can be identified or located, when the child is a ward of the state, or when the child is an unaccompanied homeless youth. The district must appoint a surrogate as soon as possible and no later than 30 days after deciding one is needed. The surrogate cannot work for the school district or an agency caring for the child, must have no conflicting interests, and must complete Ohio's surrogate parent training. A surrogate has all the rights a parent has, including consent, attending meetings and disagreeing with the school."),
            new(@"Ohio's disability categories, including developmental delay", @"glossary", @"OAC 3301-51-01(B)(10); ORC 3323.01", @"disability categories,eligibility,developmental delay,autism,specific learning disability,other health impairment",
                @"To qualify for special education in Ohio, your child must have one of the listed disabilities and, because of it, need specially designed instruction. Ohio's rules list thirteen categories: autism, deaf-blindness, emotional disturbance, hearing impairment (including deafness), intellectual disability, multiple disabilities, orthopedic impairment, other health impairment (which includes ADHD), specific learning disability (which includes dyslexia), speech or language impairment, traumatic brain injury, visual impairment (including blindness), and developmental delay. Developmental delay is a category for younger children whose development is measurably behind in areas like thinking, language, movement, social skills or self-help, when a more specific label is not yet clear. Ohio's 2023 update widened its age range: under the current rule it can be used for children ages 3 through 9, that is, until the child turns 10. A school district may choose whether to use this category, so ask how your district handles it. Two things to remember. First, a medical diagnosis alone does not make a child eligible; the evaluation team must find that the disability affects learning and that the child needs special education. Second, the category does not limit services: the IEP must address every need the ETR found, whatever the label."),
            new(@"The 30-day clock: Ohio's response to your evaluation request", @"process", @"OAC 3301-51-06(B)(3)", @"evaluation request,referral,30 days,consent,prior written notice,refusal,timeline",
                @"When you ask your school district in writing to evaluate your child for special education, Ohio's rules start a clock. Within 30 calendar days of getting your request, the district must do one of two things: 1. Agree to evaluate, and ask you to sign a consent form (Ohio form PR-05, Parent Consent for Evaluation); or 2. Refuse, by giving you prior written notice (form PR-01) that explains it does not suspect a disability and why. ""Calendar days"" means every day counts, including weekends, not just school days. The district cannot simply say nothing, and it cannot make you wait through a long round of interventions first. Interventions are allowed to go on at the same time, but they cannot be used to delay or deny an evaluation. If you receive a written refusal, you can disagree. Ask for a meeting, request mediation, file a state complaint, or file a due process complaint. If the 30 days pass with no answer at all, that is itself a violation you can point to. Tip: put your request in writing and keep a dated copy. The 30 days run from the day the district receives it, so an email with a timestamp is ideal."),
            new(@"The 60-day ETR timeline", @"process", @"OAC 3301-51-06(B)(4)", @"ETR timeline,evaluation timeline,60 days,consent,evaluation team report,deadline",
                @"Once you sign consent for an initial evaluation, Ohio gives the school district 60 days to finish the evaluation and complete the Evaluation Team Report (ETR). The clock starts on the day the district receives your signed consent, and the days are calendar days, so summer and breaks are included. Within those 60 days the team must gather information, test in every area of suspected disability, meet with you to go over the results, and decide whether your child is eligible. The ETR meeting where eligibility is decided has to happen inside the 60 days, not after. There are a few exceptions. If your child moves into the district partway through an evaluation, the district can agree with you on a different date. If you repeatedly do not make your child available for testing, the clock can pause. Otherwise, the deadline holds. If the 60 days are almost up and nothing has happened, write to the special education director, name the date you signed consent, and ask for the date of the ETR meeting. A missed deadline is a violation you can raise in a state complaint. After eligibility is decided, another clock starts: the IEP must be written within 30 calendar days."),
            new(@"What an Ohio ETR must contain", @"provisions", @"OAC 3301-51-06(F)-(G)", @"ETR contents,evaluation team report,existing data,areas of suspected disability,eligibility determination,parent input",
                @"An Ohio Evaluation Team Report (ETR) is more than test scores. Ohio's rules say the evaluation must: - Start with a review of existing data: your child's records, classroom work, teacher observations, progress-monitoring data, results of any interventions tried, and information you provide. - Assess every area of suspected disability, not just the one the school first noticed. If reading was the reason for the referral but attention or anxiety also seem to be in play, those get looked at too. - Use more than one measure. No single test can decide eligibility. - Be done in your child's language and in a way that is not biased by disability. The written report must then include a summary of what was learned, a description of your child's educational needs, and a clear eligibility decision that names the disability category. Each team member, including you, signs the report and marks whether they agree. Anyone who disagrees can attach a written statement, and that includes you. Your input is part of the record. If something important about your child is missing, say so at the meeting and ask for it to be added before you sign."),
            new(@"Reevaluation: at least every three years, sooner if needed", @"process", @"OAC 3301-51-06(D)(2)", @"reevaluation,three years,triennial,new testing,waive reevaluation",
                @"Ohio requires the school to reevaluate your child at least once every three years. The purpose is to check whether your child still has a disability, still needs special education, and whether their needs have changed. The reevaluation ends with a new ETR (Evaluation Team Report). You do not have to wait three years. You can ask for a reevaluation sooner, and the school can also propose one, for example if your child is not making progress or a new concern appears. Ohio's rule says a reevaluation happens no more than once a year unless you and the district agree otherwise, and at least once every three years unless you and the district agree it is unnecessary. A reevaluation always starts with a review of existing data. Sometimes the team decides the information on file is enough and no new testing is needed. You have the right to ask for new testing anyway, and the district has to do it if you ask. The district needs your informed written consent before new testing, just like the first evaluation. If it cannot reach you after documented, reasonable tries, it may go ahead without it."),
            new(@"Independent educational evaluation (IEE) at public expense", @"rights", @"OAC 3301-51-05; 34 CFR 300.502", @"IEE,independent evaluation,public expense,disagree with evaluation,outside evaluator",
                @"If you disagree with the school's evaluation of your child, you have the right to ask for an independent educational evaluation (IEE) at public expense. That means an evaluation done by a qualified person who does not work for the district, paid for by the district. When you make the request, Ohio's rules give the district two choices, and it must pick one without unnecessary delay: 1. Pay for the IEE; or 2. File a due process complaint to prove its own evaluation was appropriate. The district may ask why you disagree, but you do not have to explain, and it cannot make you explain before it acts. Some limits apply. You get one publicly funded IEE for each district evaluation you disagree with. The district can set reasonable criteria for the evaluator, such as location and qualifications, but they must be the same criteria it uses for its own evaluators. If a hearing officer finds the district's evaluation was appropriate, you can still get an IEE, but at your own cost. Whether public or private, the results of an IEE must be considered by the IEP team. Considered does not mean automatically adopted, so be ready to explain what the outside evaluator found."),
            new(@"Your part in the ETR meeting, and your copy of the report", @"process", @"OAC 3301-51-06(G)(1)", @"ETR meeting,eligibility determination,parent participation,copy of ETR,14 days,sign ETR,disagree",
                @"In Ohio, eligibility is decided by the evaluation team, and the rule spells out that the team includes you. The meeting is not a place where results are announced to you; it is a decision you take part in. Before the meeting, ask for a draft of the results so you are not reading them for the first time at the table. Bring notes about what you see at home and any outside reports. At the meeting, each area of the evaluation is reviewed and the team decides whether your child has a disability and needs specially designed instruction. You sign the ETR like every other member, and you check a box saying whether you agree. If you disagree with all or part of it, you can attach a written statement, and you should. Your statement becomes part of the record. Signing the ETR is not consent for services. Consent for the first IEP services is a separate decision. The district must give you a copy of the completed ETR before the IEP meeting and no later than 14 days after the eligibility decision. If you have not received it, ask in writing."),
            new(@"From ETR to IEP: 30 calendar days", @"process", @"OAC 3301-51-07", @"IEP timeline,30 days,after ETR,eligibility,initial IEP,90 days,120 days",
                @"Once the evaluation team decides your child is eligible, Ohio's rules give the district 30 calendar days to hold the IEP meeting and have an IEP in place. The IEP is the written plan of goals, services and supports that turns the ETR's findings into what actually happens at school. Ohio's IEP rule also sets two outer limits that apply whichever comes first: the IEP must be in place within 90 calendar days of your consent for the evaluation, and within 120 calendar days of the day the district received your request for one. Put together, this means a parent who asks for an evaluation should have an IEP within about four months at most. Services start as soon as possible after the IEP is written, once you give consent for the first provision of services. You can consent to some services and not others, and the school must provide the ones you agreed to. If the 30 days are slipping, write to the district and ask for a meeting date. Missed timelines are a common reason parents file state complaints, and the fix is usually quick once the deadline is named."),
            new(@"What an Ohio IEP must include", @"provisions", @"OAC 3301-51-07(E)(1); ORC 3323.011", @"IEP contents,present levels,measurable annual goals,services,frequency,duration,location,accommodations,LRE,ESY",
                @"Ohio's rule lists what every IEP must contain. Use it as a checklist when you read your child's plan: - Present levels of academic achievement and functional performance: where your child is now, in numbers and plain description, and how the disability affects their learning. - Measurable annual goals, academic and functional, written so anyone can tell whether they were met. Ohio also asks for benchmarks or short-term objectives. - How progress will be measured and when you will get progress reports. - Specially designed instruction, related services (like speech or OT) and supplementary aids and services, each with a start date, how often, how long and where. - Program modifications and supports for school staff. - An explanation of any time your child will not be with nondisabled peers (the least restrictive environment statement). - Accommodations for state and district tests, or a statement of why an alternate assessment is needed. - Whether extended school year (ESY) services are needed. - Transition services, starting with the IEP in effect when your child turns 14. If a section is blank or says ""N/A"" where your child has a need, ask why. Every need the ETR identified should be addressed somewhere in the IEP."),
            new(@"Transition planning starts at 14 in Ohio", @"provisions", @"OAC 3301-51-07(E)(2)", @"transition,age 14,postsecondary,transition services,future planning,age of majority",
                @"Federal law says transition planning must begin by the IEP in effect when a student turns 16. Ohio goes further: transition planning must be in the IEP that is in effect when your child turns 14, or earlier if the IEP team decides that is appropriate. So if your child turns 14 during the coming IEP year, this year's IEP should already include it. Transition planning means looking ahead to life after high school and writing a plan for getting there. In Ohio's IEP form this shows up as postsecondary transition, and it must include: - Measurable postsecondary goals based on age-appropriate transition assessments, covering training or education, employment and, where needed, independent living. - The transition services, including courses of study, that will help your child reach those goals. - Who is responsible for each service, and when. Your child must be invited to any IEP meeting where transition is discussed. If they cannot attend, the school must take other steps to get their preferences and interests. Ohio also requires that, by your child's 17th birthday, the IEP states that they have been told which rights will transfer to them at 18."),
            new(@"The annual IEP review", @"process", @"OAC 3301-51-07(I)", @"annual review,IEP meeting,revise IEP,progress,request a meeting",
                @"Ohio requires the IEP team to review your child's IEP at least once a year, and more often if needed. The review looks at whether the annual goals are being met and revises the plan for lack of progress, new evaluation information, new information from you, or anything else that has changed. In practice the annual review meeting produces a new IEP that runs for the next 12 months. The old IEP does not simply expire; the team must have a new one in effect before the old one ends. You do not have to wait for the annual date. You can ask for an IEP meeting at any time, and the district should schedule it promptly. Good reasons include: progress reports show little or no progress, a new diagnosis or outside evaluation, a change in behavior, or services in the IEP that are not being delivered. Before an annual review, ask for the current present levels and progress data in writing so you can compare last year's goals with what actually happened. If goals were not met, ask what will change, not just whether the goal will be carried over."),
            new(@"An IEP must be in effect when the school year starts", @"provisions", @"OAC 3301-51-07", @"start of school year,IEP in effect,new school,transfer,moving districts,implementation",
                @"Ohio's rules require that an IEP is in effect for every eligible child at the beginning of each school year. Teachers and service providers who work with your child must have access to the IEP and must be told their specific responsibilities under it before school starts, including which accommodations and modifications they must provide. The same rule covers moves. If your child transfers to a new Ohio district during the school year, the new district must provide services comparable to the old IEP, in consultation with you, until it either adopts the old IEP or writes a new one. If your child moves in from another state, the new district provides comparable services until it completes any evaluation it decides is needed and writes a new IEP. Ohio also sets a paperwork rule: within 30 calendar days after the IEP meeting, the district must give you a copy of the IEP at no cost. If the school year starts and services are not happening, do not wait for the first progress report. Write to the case manager, name the services in the IEP, and ask when they will begin."),
            new(@"Scheduling IEP meetings so you can be there", @"rights", @"OAC 3301-51-07(G)", @"meeting notice,scheduling,parent participation,mutually agreed time,interpreter,phone meeting",
                @"You have the right to take part in every meeting where your child's IEP is written, reviewed or changed, and Ohio's rules require the district to make that possible. The district must: - Tell you about the meeting early enough that you can attend. - Schedule it at a time and place you both agree on. - Tell you the purpose of the meeting, the time and location, and who will be there. - Tell you that you can invite people who know your child or have special expertise. - For transition meetings, tell you that your child will be invited. If you cannot be there in person, the district must offer other ways to take part, such as a phone or video call. If you need an interpreter, including for sign language, the district must arrange one. The school may hold a meeting without you only if it can document that it tried to reach you and agree on a time and could not. Keep your own record of calls and emails about scheduling. You can ask to reschedule. A date that only works for the school is not a ""mutually agreed"" time."),
            new(@"Changing an IEP without a full meeting", @"process", @"OAC 3301-51-07(I)", @"amend IEP,amendment,without a meeting,written agreement,changes,revised copy",
                @"Not every change to an IEP needs a full team meeting. After the annual review, you and the district can agree in writing to change the IEP without meeting. This is called an amendment. It is useful for small, clear changes, like adding an accommodation, adjusting minutes for a service, or fixing a goal that was written wrong. Two protections apply. First, the change has to be by agreement; the district cannot amend the IEP on its own and send it to you afterward. Second, you must receive a revised copy of the IEP with the changes incorporated, if you ask for one. An amendment is not the right tool for big changes. If the school wants to change your child's placement, remove a service, or rewrite most of the goals, ask for a meeting so the whole team, including the general education teacher and the person who understands the evaluation results, is part of the decision. Any change the district proposes, whether by amendment or at a meeting, still requires prior written notice explaining what is changing and why, and you can still say no."),
            new(@"Progress reports: how often Ohio schools must update you", @"provisions", @"OAC 3301-51-07(E)(1)(d)", @"progress reports,progress monitoring,report cards,data,goals,how often",
                @"An IEP goal is only useful if someone measures it. Ohio's IEP rule requires every IEP to say how your child's progress toward each annual goal will be measured, and when you will get periodic progress reports. The rule points to quarterly or other periodic reports issued at the same time as report cards. In most Ohio districts that means a progress report every grading period. A good progress report tells you three things for each goal: the goal, the data collected (numbers, not just ""making progress""), and whether your child is on track to meet the goal by the end of the IEP year. If reports say ""progressing"" without data, ask for the underlying numbers. If they say your child is not on track, ask for an IEP meeting; waiting until the annual review means losing months. If reports do not arrive at all, that is a violation of the IEP itself. Write to the case manager, name the date the IEP says reports are due, and ask for them. Keep every report you receive; together they are the best evidence of whether the plan is working."),
            new(@"Extended school year (ESY) services in Ohio", @"provisions", @"OAC 3301-51-02(G)(1)", @"ESY,extended school year,summer,regression,recoupment,summer services",
                @"Extended school year (ESY) services are special education services provided beyond the regular school year, usually over the summer, at no cost to you. ESY is not summer school and it is not automatic; the IEP team decides, child by child, whether it is needed. Ohio's rule says ESY must be provided when the IEP team determines that the services are necessary for your child to receive a free appropriate public education. The main question the team asks is whether, without ESY, your child would lose skills or knowledge over the break so seriously that it would set back their progress toward their goals. Schools often call this regression and recoupment: how much is lost, and how long it takes to get it back. Ohio's rule also says what the district cannot do. It cannot limit ESY to certain disability categories, and it cannot set a one-size-fits-all limit on the type, amount or length of ESY services. Bring data to the discussion: what happened after last summer or winter break, how long it took your child to get back to where they were, and any therapist notes. Ask the team to record its ESY decision, and the reasons, in the IEP."),
            new(@"Transportation as a related service", @"provisions", @"OAC 3301-51-10; OAC 3301-51-01(B)(56)", @"transportation,related service,bus,specialized transportation,aide on bus",
                @"Transportation is a related service under Ohio's rules. That means if your child needs special transportation to get to school or to a service because of their disability, the IEP team must consider it and, if it is needed, write it into the IEP. The district then provides it at no cost. Transportation as a related service can include travel to and from school and between schools, travel in and around the school building, and specialized equipment such as adapted vehicles, lifts, ramps or a bus aide. Ohio's transportation rule says that when a child needs transportation as a related service, district transportation staff must be consulted while the IEP is being written. Ohio also lets each district set its own reasonable limit on how long a child rides, taking into account the child's age and disability, the size of the district and traffic conditions. If your child's ride seems too long, ask for the district's travel-time standard. If your child attends a private school by your choice, they receive the same transportation as other private school students under Ohio law, not IEP-based transportation."),
            new(@"Prior written notice (PWN) in Ohio", @"rights", @"OAC 3301-51-05; 34 CFR 300.503", @"prior written notice,PWN,PR-01,refusal,proposal,notice,change",
                @"Prior written notice, or PWN, is the letter the school must send you before it changes, or refuses to change, your child's identification, evaluation, placement or services. Ohio districts use a standard form for this, called PR-01. The notice must be in plain language you can understand, in your native language if needed, and it must say: - What the district is proposing or refusing. - Why. The explanation has to be specific to your child. - What evaluations, records or reports the decision was based on. - Other options the team considered and why they were rejected. - Any other factors that mattered. - That you have procedural safeguards, and how to get a copy of them. - Where you can get help understanding the notice. A PWN is required, for example, when the district refuses to evaluate, proposes or declines a change to the IEP, changes placement, or ends eligibility. Ohio requires it within 30 days of a referral for evaluation. Why it matters: a PWN forces the district to put its reasons on paper. If you disagree, those written reasons are what a mediator, complaint investigator or hearing officer will look at. If you asked for something and got a verbal ""no,"" ask for it in writing as prior written notice."),
            new(@"Informed consent, and taking it back", @"rights", @"OAC 3301-51-05; 34 CFR 300.300", @"consent,informed consent,revoke consent,initial evaluation,initial services,reevaluation,PR-05",
                @"Consent means you have been fully told what the school wants to do, in a language you understand, and you agree in writing. Ohio requires your informed consent before: - The first evaluation of your child (form PR-05). - The first time special education services are provided. - Any reevaluation, unless the district documents that it tried and could not reach you. Consent for an evaluation is not consent for services. Those are separate decisions. Consent is voluntary. You can say no. If you refuse consent for the first services, the district cannot use mediation or due process to force them, and it is not on the hook for services it was not allowed to give. If you refuse an initial evaluation, the district may use dispute resolution to seek one, but it does not have to. You can revoke consent for special education at any time by putting it in writing. The district must then stop services, after sending you prior written notice, and cannot use dispute resolution to keep them going. Revoking is a big step: your child loses IEP protections, including discipline protections, and you would have to start with a new evaluation to get them back. Talk it through with an advocate first."),
            new(@"Seeing your child's school records", @"rights", @"OAC 3301-51-05; OAC 3301-51-04; 34 CFR 300.613", @"records,education records,access,copies,45 days,FERPA,confidentiality",
                @"You have the right to inspect and review all of your child's education records that the school collects, keeps or uses for identification, evaluation, placement or providing services. That includes evaluations, progress data, discipline records, emails and notes kept in your child's file. The district must let you review records without unnecessary delay, and in every case before any IEP meeting, before a due process hearing or resolution session, and no later than 45 days after your request. Ohio's confidentiality rule (OAC 3301-51-04) and the federal records rule set these timelines. Your right to review includes the right to have the records explained to you, to have someone you choose review them with you, and to get copies if you could not otherwise review them. The district may charge a reasonable copying fee, but cannot charge for searching or retrieving records, and cannot charge if the fee would stop you from reviewing them. If you believe a record is wrong or misleading, you can ask the district to change it. If it refuses, you can request a hearing on the record. Practical tip: request records in writing, list what you want, and ask for the full file rather than just ""the IEP."""),
            new(@"A Guide to Parent Rights: Ohio's procedural safeguards notice", @"rights", @"OAC 3301-51-05", @"procedural safeguards,procedural safeguards notice,parent rights,Whose IDEA Is This,guide to parent rights",
                @"Every state must give parents a written explanation of their rights under IDEA, called the procedural safeguards notice. Ohio's version is a booklet from the Ohio Department of Education and Workforce called ""A Guide to Parent Rights in Special Education."" Older copies were titled ""Whose IDEA Is This?""; the current guide replaced that title in 2017, and you may still hear the old name. The district must give you a copy at least once each school year, and also: - When your child is first referred for an evaluation, or you request one. - When you file your first state complaint or due process complaint in a school year. - When your child is removed from school in a way that counts as a change of placement for discipline. - Any time you ask for it. The guide explains, in one place: independent educational evaluations, prior written notice, consent, access to records, mediation, state complaints, due process hearings, your child's placement during a dispute, discipline procedures, private school placement rules, appeals and attorneys' fees. Keep a copy. Reading it before a difficult meeting is one of the best ways to walk in knowing what the school can and cannot do."),
            new(@"When you disagree: Ohio's dispute-resolution ladder", @"rights", @"OAC 3301-51-05; ORC 3323.05", @"dispute resolution,disagree,facilitated IEP meeting,mediation,state complaint,due process,options",
                @"When you and the school cannot agree, Ohio gives you several ways to resolve it. They range from informal to formal, and you can usually choose the one that fits the problem. 1. Ask for an IEP meeting. Many disagreements are solved by getting the full team back together with the data in front of them. 2. Facilitated IEP meeting. A trained, neutral facilitator from the state runs the meeting and keeps it on track. It is free and voluntary, and the team still makes the decisions. 3. Mediation. A neutral mediator helps you and the district reach a written agreement. Free, voluntary and confidential. 4. State complaint. You write to the Ohio Department of Education and Workforce describing how the district broke special education rules. The department investigates and decides within 60 days. 5. Due process complaint. A formal hearing in front of an impartial hearing officer, with a resolution session first. This is the most formal path, and most parents get an advocate or attorney. The options are not a strict ladder. You can go straight to a state complaint for a clear rule violation, or request mediation without ever filing due process. Which path fits depends on whether the issue is a rule that was broken or a judgment call you disagree with."),
            new(@"Mediation in Ohio", @"process", @"OAC 3301-51-05", @"mediation,mediator,voluntary,confidential,written agreement,dispute",
                @"Mediation is a meeting between you and the district with a neutral, trained mediator whose job is to help both sides reach an agreement. In Ohio it is arranged through the Ohio Department of Education and Workforce, and the state pays for the mediator. Ohio's rules require that mediation is: - Voluntary for both sides. Neither you nor the district can be forced into it. - Not used to delay or deny your right to a due process hearing. - Run by a qualified, impartial mediator who is not an employee of the department or of any school district serving your child. - Scheduled quickly, at a place and time convenient to you. - Confidential. Nothing said in mediation can be used as evidence later, and sessions cannot be recorded. If you reach an agreement, it is written down, signed by both sides, and becomes legally binding. A court can enforce it. Mediation works best for disagreements about judgment, such as how many minutes of a service, which placement, or how a goal is written, where both sides have room to move. You can bring an advocate. You can also request mediation at any time, whether or not a due process complaint has been filed."),
            new(@"Filing a state complaint: the 60-day investigation", @"process", @"OAC 3301-51-05", @"state complaint,complaint,Ohio Department of Education and Workforce,60 days,investigation,violation,corrective action",
                @"A state complaint is a written statement to the Ohio Department of Education and Workforce (DEW) saying that a school district has violated a special education requirement. It is free, does not require a lawyer, and works well when the problem is a rule that was clearly broken: a missed timeline, services in the IEP that were not delivered, no prior written notice, progress reports never sent. The complaint must be signed and include: your contact information, your child's name and school, a description of the problem and the facts behind it, and a proposed solution. The violation must have happened within one year before you file. You send a copy to the district at the same time. DEW then has 60 days to investigate. It may do an on-site investigation, must give you a chance to provide more information, gives the district a chance to respond, and then issues a written decision that says whether a violation occurred. If it did, the decision orders corrective action, which can include compensatory services for your child, and DEW follows up to make sure it happens. A state complaint and a due process complaint can be about the same issue, but if both are filed, the parts covered by due process are set aside until the hearing is over."),
            new(@"Due process complaints and the resolution session", @"process", @"OAC 3301-51-05", @"due process,due process complaint,hearing,resolution session,15 days,30 days,45 days,hearing officer",
                @"A due process complaint is the most formal way to resolve a special education dispute in Ohio. It leads to a hearing in front of an impartial hearing officer who can order the district to act. Parents can file about identification, evaluation, placement or whether the district provided a free appropriate public education. The complaint must concern something that happened within the past two years. The complaint must describe the problem and a proposed solution and be sent to the district and to the Ohio Department of Education and Workforce. Filing starts a set of clocks: - Within 15 days, the district must hold a resolution session with you and relevant IEP team members to try to settle. You and the district can agree to skip it or use mediation instead. - If it is not resolved within 30 days of the district receiving the complaint, the hearing timeline begins. - The hearing officer must issue a written decision within 45 days after that 30-day period, unless a deadline extension is granted. Either side can appeal the decision to a state-level review officer within 45 days, and after that to court. Because the process is legal and the district will have counsel, most parents work with an advocate or an attorney. Ohio's parent rights guide and the state's parent training center can point you to help."),
            new(@"Stay-put: nothing changes while you dispute", @"rights", @"OAC 3301-51-05", @"stay-put,pendency,current placement,due process,change of placement,dispute",
                @"Stay-put is a protection that kicks in when you file a due process complaint. While the case is pending, including any appeal, your child stays in their current educational placement unless you and the district agree otherwise. The district cannot use the dispute as a reason to move your child, drop services or change the IEP. ""Current placement"" generally means the last IEP that you and the district agreed on and that was being implemented. If the dispute is about a first-time admission to school, your child, with your consent, is placed in the regular public school program until the case is decided. Stay-put does not apply to state complaints or mediation on their own, only to due process. It also has an exception for discipline: if your child has been moved to an interim alternative educational setting for a weapons, drugs or serious bodily injury incident, or a hearing officer ordered that placement, your child stays in the interim setting during an appeal, for up to 45 school days. If the district changes placement while a due process case is pending, tell the hearing officer right away. Stay-put is enforceable."),
            new(@"Discipline: the 10-day rule and manifestation determination", @"rights", @"OAC 3301-51-05", @"discipline,suspension,expulsion,10 days,manifestation determination,MDR,change of placement,behavior",
                @"A child with an IEP can be disciplined like any other student, up to a point. Ohio's rules, following IDEA, set that point at ten school days. The school can remove your child from their placement, by suspension or otherwise, for up to 10 school days in a school year without providing services, as long as it treats nondisabled children the same way. Once removals pass 10 days in a year, services must continue so your child can keep working on IEP goals. A removal of more than 10 consecutive school days, or a pattern of shorter removals that adds up to a change of placement, triggers a manifestation determination review (MDR). Within 10 school days of the decision to remove, the district, you and relevant IEP team members must meet and answer two questions: 1. Was the behavior caused by, or directly and substantially related to, your child's disability? 2. Was the behavior the direct result of the school's failure to implement the IEP? If the answer to either is yes, the behavior is a manifestation. The school must return your child to their placement (unless you agree to a change), do a functional behavioral assessment, and write or revise a behavior intervention plan. If the answer to both is no, the school may discipline your child as it would any student, but services continue. You can appeal an MDR decision through an expedited due process hearing."),
            new(@"Interim alternative settings: weapons, drugs and serious injury", @"rights", @"OAC 3301-51-05", @"interim alternative educational setting,IAES,45 school days,weapons,drugs,serious bodily injury,discipline",
                @"There are three situations in which a school can move a child with a disability to an interim alternative educational setting (IAES) for up to 45 school days, whether or not the behavior was a manifestation of the disability: 1. The child carries or possesses a weapon at school, on school premises, or at a school function. 2. The child knowingly possesses or uses illegal drugs, or sells or solicits a controlled substance, at school or a school function. 3. The child inflicts serious bodily injury on another person at school or a school function. Even in these cases the protections do not disappear. The district must send you prior written notice and a copy of the procedural safeguards on the day it makes the decision. A manifestation determination review still has to be held within 10 school days. The IEP team decides what the interim setting is. Services must continue there so your child can keep progressing toward IEP goals, and the child must receive, as appropriate, a functional behavioral assessment and behavior services. Outside of those three situations, a district that believes keeping a child in their placement is substantially likely to injure the child or others cannot act alone; it must ask a hearing officer, who can order an interim setting of up to 45 school days. You can challenge an IAES decision through an expedited due process hearing."),
            new(@"Transfer of rights at 18 in Ohio", @"process", @"OAC 3301-51-05; OAC 3301-51-07(E)(3)", @"transfer of rights,age of majority,18,adult student,guardianship,supported decision-making",
                @"In Ohio, the age of majority is 18. When your child turns 18, every right that belonged to you as a parent under IDEA transfers to them: consent, attending meetings, receiving notices, agreeing or disagreeing with the IEP, and filing complaints. You still receive copies of notices, but your child is the decision-maker. Ohio's rules make sure this is not a surprise. By your child's 17th birthday, the IEP must include a statement that your child has been told which rights will transfer to them at 18. The transfer does not happen if your child has been found incompetent under Ohio law and a guardian has been appointed. Short of guardianship, families use tools such as a power of attorney for education or supported decision-making agreements so the young adult keeps their rights but has help using them. Guardianship is a serious court process that removes rights, so it is worth talking with an attorney or Ohio's disability rights organizations before choosing it. Whatever route you take, start the conversation with your child and the IEP team early, ideally at the transition meeting when your child is 14 or 15."),
            new(@"Least restrictive environment (LRE) in Ohio", @"provisions", @"OAC 3301-51-09", @"LRE,least restrictive environment,general education,inclusion,supplementary aids and services,removal",
                @"Least restrictive environment, or LRE, is the rule that children with disabilities are educated with children who do not have disabilities to the maximum extent appropriate. Ohio's rule starts from a presumption: the general education classroom is the starting point for every child. A child can be placed in a separate class, separate school or other setting only if the nature or severity of the disability is such that education in regular classes, with the use of supplementary aids and services, cannot be achieved satisfactorily. Read that carefully. The school has to show that it tried, or seriously considered, supports in the general classroom, such as an aide, modified materials, assistive technology, co-teaching or a behavior plan, and that they would not work. ""We do not have that program here"" is not a reason. LRE also covers the rest of the school day. Ohio's rule requires that your child takes part with nondisabled peers in lunch, recess, clubs, sports and other nonacademic activities to the maximum extent appropriate, with the supports the IEP team decides are needed. Every IEP must explain any time your child will not be with nondisabled peers. If the explanation is missing or vague, ask the team to justify it."),
            new(@"The continuum of placements", @"provisions", @"OAC 3301-51-09(C)(2)", @"continuum of placements,placement options,resource room,special class,special school,home instruction",
                @"Ohio requires every school district to have a range of placement options available so that the IEP team can match the setting to the child rather than the child to the setting. The rule calls this the continuum of alternative placements. It must include: - Instruction in regular classes, with the supports the child needs. - Special classes. - Special schools. - Home instruction. - Instruction in hospitals and institutions. Alongside the regular class option, the district must make supplementary services available, such as a resource room or itinerant (traveling) instruction from an intervention specialist. Two things follow from this. First, the district cannot say a placement ""does not exist"" for your child; the continuum is a requirement, and a district that lacks an option must arrange it, including through another district or agency. Second, placement is a decision, not a menu. The team picks the least restrictive option on the continuum where your child's IEP can be carried out satisfactorily, and revisits that decision at least once a year. If you are told your child must attend a particular program because it is the only one offered, ask the team to walk through the continuum and explain why each less restrictive option was rejected."),
            new(@"Where your child is placed, and who decides", @"rights", @"OAC 3301-51-09(D)", @"placement decision,placement,neighborhood school,close to home,IEP team,annually",
                @"Placement is the setting where your child's IEP will be delivered. In Ohio, the placement decision is made by a group of people that includes you and others who know your child, the evaluation data and the placement options. It is not a decision the district makes alone and then announces. Ohio's rule sets the ground rules for the decision: - Placement is decided at least once a year. - It is based on your child's IEP, so the IEP is written first and the placement follows, not the other way around. - It must be as close as possible to your child's home. - Unless the IEP requires something else, your child attends the school they would attend if they did not have a disability. - The team must consider any potential harmful effect of a placement on your child or on the quality of services. A change of placement is a significant decision, and the district must give you prior written notice before making one. If you disagree, the dispute-resolution options apply, and stay-put protects the current placement while a due process case is pending. If your child is being sent to a school across the district when a closer school could serve them with supports, ask the team to explain, in writing, why."),
            new(@"Preschool special education: ages 3 through 5", @"process", @"OAC 3301-51-11", @"preschool,ages 3-5,early childhood,preschool special education,eligibility,itinerant services",
                @"In Ohio, special education starts at age 3. A child who is at least 3 and not yet 6 (or who is not yet of compulsory school age and not enrolled in kindergarten) can be evaluated and, if eligible, receive preschool special education from the school district where the family lives. Preschool eligibility uses the same disability categories as school-age children, and Ohio also allows developmental delay, a category for young children whose development is measurably behind in physical, thinking, communication, social-emotional or self-help skills. The evaluation must draw on several sources, including observations in more than one setting, information from parents and caregivers, and at least one standardized assessment. Services can be delivered in several ways: in a preschool special education classroom, in a community preschool or child care setting with a traveling (itinerant) intervention specialist, or, in some cases, at home. Ohio sets minimum amounts of service and staffing ratios for these settings. Everything else in the Operating Standards applies to preschoolers too: an ETR, an IEP with measurable goals, prior written notice, consent and your right to disagree. Ask your district's preschool special education coordinator how to request an evaluation."),
            new(@"Moving from Help Me Grow to preschool special education", @"process", @"OAC 3301-51-11(D)(3)", @"Help Me Grow,Part C,early intervention,transition,third birthday,IEP by age 3,transition conference",
                @"Ohio's early intervention program for babies and toddlers with delays or disabilities is called Help Me Grow (this is Part C of IDEA). It ends on a child's third birthday. If your child may need special education after that, Ohio's rules require a planned hand-off to the school district so there is no gap. Here is how it works: - Help Me Grow notifies your school district that your child is coming, and a transition planning conference is held. The conference can happen as early as nine months before your child's third birthday. - The district treats the notification as a referral and evaluates your child, with your consent. - If your child is eligible, the district must have an IEP written and being implemented by your child's third birthday. Ohio's rule is firm about this date; districts that miss it face state corrective action. If your child's birthday falls in the summer, the IEP team decides when services start, but the IEP itself must still be in place by the birthday. What you can do: keep your Help Me Grow evaluations and progress notes, share them with the district, and ask for the transition conference if you have not heard about one by the time your child is about two years and three months old."),
            new(@"How to ask for an ETR in Ohio (sample letter outline)", @"tips", @"OAC 3301-51-06(B)(3)", @"request evaluation,sample letter,how to ask,ETR request,written request,30 days",
                @"You can ask your school district to evaluate your child at any time. Put it in writing. A dated letter or email starts Ohio's 30-day clock and gives you a record. Address it to the school principal and the district's director of special education, and keep a copy. Outline of the letter: 1. Who you are and who your child is: full name, date of birth, school and grade. 2. What you are asking for: ""I am requesting that the district evaluate my child for special education under IDEA and Ohio's Operating Standards (OAC 3301-51-06)."" 3. Why: two or three specific concerns in plain words. For example, ""reads well below grade level despite tutoring,"" ""cannot stay in the classroom for more than a few minutes,"" ""speech is hard for others to understand."" 4. Areas you want assessed: reading, writing, math, speech and language, attention, behavior, social skills, motor skills, or whatever fits. 5. What you have: mention any outside reports or diagnoses and offer to share them. 6. The ask: ""Please send me the consent form or, if the district declines, prior written notice within 30 calendar days, as required."" 7. Your contact details and signature. After sending, note the date. If you hear nothing in 30 days, write again and refer to the first letter."),
            new(@"What to bring to an ETR meeting", @"tips", @"OAC 3301-51-06(G)", @"ETR meeting,prepare,what to bring,eligibility meeting,checklist,parent input",
                @"The ETR meeting is where the evaluation team, including you, decides whether your child is eligible for special education. Walking in prepared makes you a real member of the team instead of an audience. Bring: - The draft ETR, if the district gave you one, with your notes and questions written in the margins. - Any outside evaluations or medical diagnoses, with extra copies for the team. - A one-page summary of your child: strengths, what is hard, what helps at home, and what you are most worried about. Ask that it be included in the report as parent input. - Samples of schoolwork and any notes from teachers, tutors or therapists. - Report cards, past progress reports and attendance or discipline records if they are relevant. - A list of questions. Good ones: ""Which areas were assessed, and were any areas of concern not assessed?"" ""What do these scores mean for how my child learns?"" ""What does my child need that they are not getting now?"" - Someone to support you, such as a co-parent, relative, friend or advocate, and a notebook or a laptop for notes. Remember: you sign the ETR and mark whether you agree, and you can attach a written statement. Do not feel pressed to sign on the spot if you need time to read it. Ask for a copy and a few days."),
            new(@"Reading an Ohio IEP form section by section", @"tips", @"OAC 3301-51-07(E)", @"IEP form,PR-07,how to read,sections,future planning,special instructional factors,profile,goals,services",
                @"Ohio districts use a standard IEP form (PR-07), so most Ohio IEPs follow the same order. Here is what to look for in each part: - Future planning: what you and your child hope for in the years ahead. Make sure your words are here. - Special instructional factors: behavior, limited English, blindness, deafness, communication, assistive technology. A ""yes"" here must be addressed somewhere in the IEP. - Profile: the present levels. Look for numbers, dates and a clear picture of your child, not just labels. - Postsecondary transition (age 14 and up): goals for after high school and the services to get there. - Measurable annual goals: each goal should say what, how much, by when and how it is measured, with benchmarks or objectives and a progress-reporting plan. - Specially designed services: instruction, related services, accommodations, modifications and supports for staff, each with provider, start date, amount, frequency and location. - Transportation: whether special transportation is needed. - Nonacademic and extracurricular activities. - General factors and least restrictive environment: why any time away from nondisabled peers is necessary. - Statewide and district testing: accommodations or an alternate assessment. - Meeting participants and signatures. If a section is blank or generic, that is your question for the team."),
            new(@"If the school says no: your next three options", @"tips", @"OAC 3301-51-05", @"school says no,refusal,next steps,prior written notice,mediation,state complaint,IEP meeting",
                @"A ""no"" from the school is not the end of the conversation. Whatever you asked for, an evaluation, a service, a placement change, an accommodation, Ohio's rules give you a path forward. First, get the no in writing. Ask for prior written notice. The district must explain what it is refusing, why, what information it relied on and what other options it considered. A verbal no becomes much harder to defend once it has to be written down, and sometimes the request gets reconsidered at this step. Then choose one of these three options: 1. Ask for an IEP meeting, or a facilitated IEP meeting with a neutral state facilitator. Bring data: progress reports, work samples, outside evaluations. Many refusals are reversed when the whole team looks at the numbers together. 2. Request mediation. A neutral mediator helps you and the district reach a written, binding agreement. It is free, confidential and often faster than a formal complaint. 3. File a state complaint if a rule was broken (a timeline missed, a service not delivered, no notice given), or a due process complaint if the disagreement is about what your child needs. Whichever you choose, keep every email and notice. Written records are what decide these disputes."),
        };
    }
}
